def _calibration(panel, x):
    from scipy.optimize import least_squares
    from scipy.optimize import minimize_scalar
    (u, v) = (panel['u'], panel['v'])
    a = _aff(u)
    keep = np.ones(len(u), dtype=bool)
    for _ in range(5):
        err = np.linalg.norm(v - a @ _ls(a[keep], v[keep]), axis=1)
        keep = err < max(0.005, 3 * np.median(err))
    affine = _ls(a[keep], v[keep])
    ident = np.eye(u.shape[1])

    def design(z, rate):
        eye = np.broadcast_to(ident, (len(z),) + ident.shape)
        return np.concatenate((eye, z[:, :, None] * eye, (z ** 3)[:, :, None], np.sin(rate * np.roll(z, 2, axis=1))[:, :, None]), axis=2)
    for _ in range(3):

        def fit(rate):
            d = design(u[keep], rate).reshape(-1, 10)
            target = v[keep].ravel()
            coef = _ls(d, target)
            return (np.mean((d @ coef - target) ** 2), coef)
        rate = minimize_scalar(lambda r: fit(r)[0], bounds=(1.4, 3.5), method='bounded').x
        coef = fit(rate)[1]
        err = np.linalg.norm(design(u, rate) @ coef - v, axis=1)
        new = err < max(0.001, 4 * np.median(err))
        if new.sum() < 20 or np.array_equal(new, keep):
            break
        keep = new
    init = _ls(affine[1:].T, (x - affine[0]).T).T
    return np.array([least_squares(lambda z: design(z[None], rate)[0] @ coef - row, z0, gtol=1e-11).x for (row, z0) in zip(x, init)])

def _features(study, x):
    from scipy.optimize import minimize_scalar
    z = _calibration(study['panel_a'], x)
    (u, v1, v2) = (study['panel_c'][k] for k in ('u', 'v1', 'v2'))

    def cyc(w):
        return _aff(w * np.roll(w, -1, axis=1))

    def cos(w, r):
        return _aff(np.cos(r * w))

    def fit(r):
        a = cos(u, r)
        b = _ls(a, v2)
        return (np.mean((a @ b - v2) ** 2), b)
    r = minimize_scalar(lambda r: fit(r)[0], bounds=(1.8, 2.9), method='bounded').x
    c = cyc(z) @ _ls(cyc(u), v1)
    d = cos(z, r) @ fit(r)[1]
    return np.column_stack((_aff(z), c, d, (c[:, :, None] * d[:, None, :]).reshape(len(z), 16)))

def mon(x, k):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(x[:, j], axis=1) for j in combinations_with_replacement(range(4), k)])

def branch(u, v, f):
    from scipy.optimize import least_squares

    def res(k):
        a = f(u, k)
        return (a @ ls(a, v) - v).ravel()
    sol = min((least_squares(res, [k], bounds=(0.05, 8), max_nfev=80) for k in [0.55, 1.25, 2.15, 3.5]), key=lambda a: np.mean(a.fun ** 2))
    k = sol.x
    a = f(u, k)
    q = np.linalg.svd(a, full_matrices=False)[0]
    loo = sol.fun.reshape(v.shape) / np.maximum(0.01, 1 - (q * q).sum(1))[:, None]
    return (np.sqrt(np.mean(sol.fun ** 2)), np.sqrt(np.mean(loo ** 2)), k[0])
